    exists regs',
      msteps SEGS (mkst regs (0x1937c : word) m rom) (mkst regs' (0x19284 : word) m rom)
      /\ getr regs' 10 = Z_to_bv 64 0x10758 /\ getr regs' 11 = Z_to_bv 64 0x10fdf
      /\ regs_agree (fun r => In r [10; 11]%list) regs regs'.
